import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './e2e',
  outputDir: './playwright-artifacts/test-results',
  reporter: [
    ['list'],
    ['html', { outputFolder: 'playwright-artifacts/report', open: 'never' }],
  ],
  timeout: 30_000,
  expect: {
    timeout: 10_000,
  },
  use: {
    baseURL: 'http://127.0.0.1:30322',
    channel: process.env.PLAYWRIGHT_CHANNEL || 'chrome',
    screenshot: 'only-on-failure',
    trace: 'retain-on-failure',
    viewport: { width: 1440, height: 1000 },
  },
  projects: [
    {
      name: 'chrome',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
  webServer: {
    command:
      'NX_DAEMON=false ./node_modules/.bin/nx serve orders --configuration=development-staging --host 127.0.0.1 --poll=1000',
    url: 'http://127.0.0.1:30322',
    reuseExistingServer: !process.env.CI,
    timeout: 120_000,
  },
});
